<script setup lang="ts">import { computed,ref } from 'vue';import { ElButton,ElForm,ElFormItem,ElInput,ElMessage,ElMessageBox,ElOption,ElSelect,ElSwitch,ElUpload } from 'element-plus';import { QiArrowUpBracket } from 'qingicon-vue';import { usePrototypeAccess } from '#/features/team/access-store';import { roleName } from '#/features/team/role-catalog';import { useTeamStore } from '#/features/team/team-store';import { useDemoServiceStore } from '#/features/service/demo-store';const access=usePrototypeAccess(),team=useTeamStore(),store=useDemoServiceStore();const profile=ref({...store.settingsFor(access.currentId)}),password=ref({current:'',next:'',confirm:''});const member=computed(()=>access.current);const teams=computed(()=>member.value?.teamIds.map(id=>team.teamById(id)?.name).filter(Boolean).join('、'));function upload(file:any){const reader=new FileReader();reader.onload=()=>profile.value.avatar=String(reader.result);reader.readAsDataURL(file.raw);return false}function save(){if(!profile.value.nickname.trim())return ElMessage.error('请输入昵称');store.savePersonal(access.currentId,profile.value);ElMessage.success('个人资料已保存')}async function savePassword(){if(!password.value.current)return ElMessage.error('请输入原密码');if(!/^(?=.*[A-Za-z])(?=.*\d).{8,}$/.test(password.value.next))return ElMessage.error('新密码至少 8 位，且包含字母和数字');if(password.value.next!==password.value.confirm)return ElMessage.error('两次输入的新密码不一致');try{await ElMessageBox.confirm('修改密码后，将退出当前账号并停止接待。','确认修改密码？',{confirmButtonText:'修改',cancelButtonText:'取消',type:'warning'})}catch{return}store.savePersonal(access.currentId,{accepting:false});password.value={current:'',next:'',confirm:''};ElMessage.success('密码已修改，Mock 登录状态已失效')}</script>
<template><main class="personal-page"><header><h1>个人中心</h1></header><section><h2>个人资料</h2><ElForm label-position="top"><ElFormItem label="头像"><ElUpload :auto-upload="false" :show-file-list="false" accept="image/*" @change="upload"><button class="avatar-upload"><img v-if="profile.avatar" :src="profile.avatar"/><QiArrowUpBracket v-else :size="28"/></button></ElUpload></ElFormItem><ElFormItem label="用户名"><ElInput :model-value="member?.account" disabled/></ElFormItem><ElFormItem label="昵称"><ElInput v-model="profile.nickname" maxlength="32" show-word-limit/></ElFormItem><ElFormItem label="所属角色"><ElInput :model-value="member?.role==='Owner'?'Owner':roleName(member?.role||'')" disabled/></ElFormItem><ElFormItem label="所属团队"><ElInput :model-value="teams" disabled/></ElFormItem><ElFormItem label="接受聊天"><ElSwitch v-model="profile.accepting" active-text="在线" inactive-text="离线"/></ElFormItem><ElFormItem label="界面语言"><ElSelect v-model="profile.locale"><ElOption label="简体中文" value="zh-CN"/><ElOption label="English" value="en-US"/></ElSelect></ElFormItem><ElButton type="primary" @click="save">保存资料</ElButton></ElForm></section><section><h2>修改密码</h2><ElForm label-position="top"><ElFormItem label="原密码"><ElInput v-model="password.current" type="password" show-password/></ElFormItem><ElFormItem label="新密码"><ElInput v-model="password.next" type="password" show-password/></ElFormItem><ElFormItem label="确认新密码"><ElInput v-model="password.confirm" type="password" show-password/></ElFormItem><ElButton @click="savePassword">修改密码</ElButton></ElForm></section></main></template>
<style scoped>.personal-page{padding:26px;background:#f4f6f8;min-height:calc(100vh - 70px)}h1{font-size:22px;font-weight:650;margin-bottom:20px}section{background:#fff;padding:24px;border-radius:10px;max-width:850px;margin-bottom:18px}h2{font-size:18px;font-weight:650;margin-bottom:20px}.el-form{max-width:560px}.el-select{width:100%}.avatar-upload{display:grid;width:76px;height:76px;place-items:center;border-radius:50%;background:#f1f3f5;color:#536173;overflow:hidden}.avatar-upload img{width:100%;height:100%;object-fit:cover}</style>
